static const char str2816[] = "static inline void *__uya_memcpy(void *dest, const void *src, size_t n) {\n";
static const char str2817[] = "    char *d = (char *)dest; const char *s = (const char *)src;\n";
static const char str2818[] = "    for (size_t i = 0; i < n; i++) d[i] = s[i];\n";
