static const char str2820[] = "static inline int __uya_memcmp(const void *s1, const void *s2, size_t n) {\n";
static const char str2821[] = "    const unsigned char *a = (const unsigned char *)s1, *b = (const unsigned char *)s2;\n";
static const char str2822[] = "    for (size_t i = 0; i < n; i++) { if (a[i] != b[i]) return a[i] - b[i]; } return 0;\n";
static const char str2823[] = "// syscall write - 写入文件描述符\n";
static const char str2824[] = "static long uya_write(int fd, const char *buf, unsigned long len) {\n";
static const char str2825[] = "    long ret;\n";
static const char str2826[] = "    __asm__ volatile (\"syscall\" : \"=a\"(ret) : \"a\"(1), \"D\"(fd), \"S\"(buf), \"d\"(len) : \"rcx\", \"r11\", \"memory\");\n";
static const char str2827[] = "    return ret;\n";
static const char str2828[] = "// strlen - 计算字符串长度\n";
static const char str2829[] = "static unsigned long uya_strlen(const char *s) {\n";
static const char str2830[] = "    unsigned long len = 0;\n";
static const char str2831[] = "    while (s[len]) len++;\n";
static const char str2832[] = "    return len;\n";
static const char str2833[] = "// 打印 i32（--nostdlib 下避免依赖 printf 的 %d）\n";
static const char str2834[] = "static void uya_print_i32(int32_t value) {\n";
static const char str2835[] = "    char digits[16];\n";
static const char str2836[] = "    char out[16];\n";
static const char str2837[] = "    int32_t temp = value;\n";
static const char str2838[] = "    if (temp == 0) { (void)uya_write(1, \"0\", 1); return; }\n";
static const char str2839[] = "    if (temp < 0) { (void)uya_write(1, \"-\", 1); temp = -temp; }\n";
static const char str2840[] = "    while (temp > 0) { digits[len++] = (char)('0' + (temp % 10)); temp /= 10; }\n";
static const char str2841[] = "    for (unsigned long i = 0; i < len; i++) out[i] = digits[len - 1 - i];\n";
static const char str2842[] = "    (void)uya_write(1, out, len);\n";
static const char str2843[] = "// brk syscall - 最小堆实现\n";
static const char str2844[] = "static unsigned long uya_brk(unsigned long addr) {\n";
static const char str2845[] = "    unsigned long ret;\n";
static const char str2846[] = "    __asm__ volatile (\"syscall\" : \"=a\"(ret) : \"a\"(12), \"D\"(addr) : \"rcx\", \"r11\", \"memory\");\n";
static const char str2847[] = "static unsigned char *uya_heap_cur = (unsigned char *)0;\n";
static const char str2848[] = "static unsigned char *uya_heap_end = (unsigned char *)0;\n\n";
static const char str2849[] = "void *malloc(size_t size) {\n";
static const char str2850[] = "    if (size == 0) size = 1;\n";
static const char str2851[] = "    size = (size + 15UL) & ~15UL;\n";
static const char str2852[] = "    if (uya_heap_cur == (unsigned char *)0) {\n";
static const char str2853[] = "        unsigned long cur = uya_brk(0);\n";
static const char str2854[] = "        if (cur == 0) return (void *)0;\n";
static const char str2855[] = "        uya_heap_cur = (unsigned char *)cur;\n";
static const char str2856[] = "        uya_heap_end = (unsigned char *)cur;\n";
static const char str2857[] = "    unsigned long need = (unsigned long)uya_heap_cur + size;\n";
static const char str2858[] = "    if ((unsigned char *)need > uya_heap_end) {\n";
static const char str2859[] = "        unsigned long target = need;\n";
static const char str2860[] = "        unsigned long got = uya_brk(target);\n";
static const char str2861[] = "        if (got < target) return (void *)0;\n";
static const char str2862[] = "        uya_heap_end = (unsigned char *)got;\n";
static const char str2863[] = "    void *p = (void *)uya_heap_cur;\n";
static const char str2864[] = "    uya_heap_cur += size;\n";
static const char str2865[] = "    return p;\n";
static const char str2866[] = "void free(void *ptr) { (void)ptr; }\n\n";
static const char str2867[] = "void *realloc(void *ptr, size_t new_size) {\n";
static const char str2868[] = "    if (ptr == (void *)0) return malloc(new_size);\n";
static const char str2869[] = "    if (new_size == 0) { free(ptr); return (void *)0; }\n";
static const char str2870[] = "    void *np = malloc(new_size);\n";
static const char str2871[] = "    if (np == (void *)0) return (void *)0;\n";
static const char str2872[] = "    __uya_memcpy(np, ptr, new_size);\n";
static const char str2873[] = "    return np;\n";
static const char str2874[] = "int32_t printf(uint8_t *fmt, ...) {\n";
static const char str2875[] = "    if (fmt == (uint8_t *)0) return -1;\n";
static const char str2876[] = "    unsigned long n = uya_strlen((const char *)fmt);\n";
